    var maxLeft = window.scrollX + document.documentElement.clientWidth - el.offsetWidth - 10;
    var left = Math.min(Math.max(window.scrollX + 10, r.left + window.scrollX - 160), Math.max(window.scrollX + 10, maxLeft));
